package com.vinnyvangogh.buildguard;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Whether this account may do a quest — the reason this plugin exists.
 *
 * <p>A port of questpath's {@code internal/planner/classify.go} and {@code
 * guard.go}, carried across with its generated vectors. It
 * answers the same seven statuses from the same inputs, and
 * {@code PlannerVectorsTest} runs it against 218 verdicts generated by the Go
 * original. That test is not a nicety: two implementations of one rule set
 * drift, and both render confidently, so the only thing separating "agrees"
 * from "appears to agree" is the vectors.
 *
 * <p>The correction the engine exists for is that checking rewards alone is
 * not enough. Land of the Goblins is not blocked by anything it grants — it is
 * blocked because a prerequisite <em>requires</em> Attack 15 and Prayer 25
 * while both are capped at 1. So both sides are checked, and a permanently
 * blocked prerequisite poisons everything downstream of it.
 */
class QuestClassifier
{
	private final QuestGraph graph;
	private final PlayerState account;
	private final Map<Long, QuestStatus> memo = new HashMap<>();

	/** Ids currently being classified, so a prerequisite cycle is detected. */
	private final Set<Long> visiting = new HashSet<>();

	/**
	 * The boost table, used to check a shortfall is small enough to drink
	 * away.
	 *
	 * Built from the graph rather than passed in, so every caller gets the
	 * check whether or not it knew to ask for it. That matters: the bug this
	 * closes was that nobody asked.
	 */
	private final Boosts boosts;

	QuestClassifier(QuestGraph graph, PlayerState account)
	{
		this.graph = graph;
		this.account = account;
		this.boosts = new Boosts(graph.boosts());
	}

	/**
	 * The verdict for one quest, or null when the graph does not carry it.
	 *
	 * Null rather than a status: a quest this bundle has never heard of is a
	 * stale bundle, not an eligible quest, and the two must not render the
	 * same.
	 */
	QuestStatus classify(long questId)
	{
		QuestGraph.Quest quest = graph.get(questId);
		if (quest == null)
		{
			return null;
		}
		return classify(quest);
	}

	QuestStatus classify(QuestGraph.Quest quest)
	{
		QuestStatus memoised = memo.get(quest.id());
		if (memoised != null)
		{
			return memoised;
		}
		if (!visiting.add(quest.id()))
		{
			// A prerequisite cycle. The Go side errors here; the plugin cannot
			// usefully surface an error per quest, and treating a cycle as
			// unreachable is true in the only sense that matters — you cannot
			// do it.
			return QuestStatus.UNREACHABLE;
		}
		try
		{
			QuestStatus status = compute(quest);
			memo.put(quest.id(), status);
			return status;
		}
		finally
		{
			visiting.remove(quest.id());
		}
	}

	private QuestStatus compute(QuestGraph.Quest quest)
	{
		if (account.isComplete(quest.name()))
		{
			return QuestStatus.COMPLETE;
		}

		// The build guard first: a quest that breaks a rule is off the table
		// regardless of whether its prerequisites are done or its levels met.
		if (blocksBuild(quest))
		{
			return QuestStatus.BUILD_BLOCKED;
		}

		// Any prerequisite that is permanently blocked poisons this one. This
		// is the transitive half of the correction, and the reason a quest can
		// be unreachable while asking nothing untoward itself.
		boolean anyMissing = false;
		for (long prerequisiteId : quest.prerequisites())
		{
			QuestGraph.Quest prerequisite = graph.get(prerequisiteId);
			if (prerequisite == null)
			{
				// A prerequisite the bundle does not carry. Treated as
				// missing rather than ignored: assuming it is fine would turn
				// a stale bundle into a false "eligible".
				anyMissing = true;
				continue;
			}
			// A started-only prerequisite is satisfied by having begun it, and
			// is asked of the account directly rather than through classify():
			// its own status is beside the point, because this quest never
			// asked for it to be finished. Demanding COMPLETE would block a
			// quest the account can genuinely do. The Go planner applies
			// exactly this rule; the two must agree or the golden vectors
			// diverge, which is what PlannerVectorsTest is for.
			if (quest.requiresStartedOnly(prerequisiteId))
			{
				if (!account.hasStarted(prerequisite.name()))
				{
					anyMissing = true;
				}
				continue;
			}
			QuestStatus prerequisiteStatus = classify(prerequisite);
			if (prerequisiteStatus.permanent())
			{
				return QuestStatus.UNREACHABLE;
			}
			if (prerequisiteStatus != QuestStatus.COMPLETE)
			{
				anyMissing = true;
			}
		}

		SkillGaps gaps = skillGaps(quest);

		// Precedence matters and matches the Go original: a quest short on
		// levels reports that even when it is also short a prerequisite,
		// because training is the thing the player can start on now.
		if (gaps.anyGap && !gaps.allBoostable)
		{
			return QuestStatus.SKILL_BLOCKED;
		}
		if (anyMissing)
		{
			return QuestStatus.QUEST_BLOCKED;
		}
		if (gaps.allBoostable && gaps.anyGap)
		{
			return QuestStatus.BOOSTABLE;
		}
		return QuestStatus.ELIGIBLE;
	}

	/**
	 * Whether this quest itself breaks a blocking build rule.
	 *
	 * Both sides, which is the correction: a reward that would push a capped
	 * skill past its cap, and a requirement that demands a level above one.
	 * Boostable is deliberately not consulted on the requirement side — a
	 * boost is relative to the base level, so a capped skill cannot reach a
	 * boostable requirement above the cap.
	 */
	private boolean blocksBuild(QuestGraph.Quest quest)
	{
		for (QuestGraph.Reward reward : quest.rewards())
		{
			BuildRule rule = account.ruleFor(reward.skill());
			if (rule == null || !rule.blocking())
			{
				continue;
			}
			if (BuildRule.NO_XP.equals(rule.type()))
			{
				// Any experience at all. XP that does not raise the level is
				// still XP, and a NO_XP account has said no to all of it.
				return true;
			}
			if (BuildRule.HARD_CAP.equals(rule.type()) && rule.hasValue())
			{
				long after = account.experienceIn(reward.skill()) + (long) Math.floor(reward.xp());
				if (XpTable.levelFor(after) > rule.value())
				{
					return true;
				}
			}
		}

		for (QuestGraph.Requirement requirement : quest.requirements())
		{
			BuildRule rule = account.ruleFor(requirement.skill());
			if (rule == null || !rule.blocking())
			{
				continue;
			}
			int cap = BuildRule.NO_XP.equals(rule.type()) ? startLevelFor(requirement.skill()) : rule.value();
			if (BuildRule.HARD_CAP.equals(rule.type()) && !rule.hasValue())
			{
				continue;
			}
			if (requirement.level() > cap)
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * The level a NO_XP skill can still legitimately be at.
	 *
	 * Hitpoints starts at 10 and every other skill at 1, so a NO_XP Hitpoints
	 * account still meets a requirement of 10. Treating the floor as 1 would
	 * block quests that ask for nothing the account has not already got.
	 */
	private static int startLevelFor(String skill)
	{
		return "hitpoints".equalsIgnoreCase(skill) ? 10 : 1;
	}

	private SkillGaps skillGaps(QuestGraph.Quest quest)
	{
		SkillGaps gaps = new SkillGaps();
		gaps.allBoostable = true;
		for (QuestGraph.Requirement requirement : quest.requirements())
		{
			int have = account.levelIn(requirement.skill());
			if (have >= requirement.level())
			{
				continue;
			}
			gaps.anyGap = true;
			// Permission and magnitude, and it used to be only the first.
			// The wiki's marker says a boost is allowed for this
			// requirement; it says nothing about size, so a fifty-level
			// shortfall passed as readily as a one-level one and the quest
			// came back BOOSTABLE either way. Both have to hold now: the
			// requirement must allow a boost, and something drinkable must
			// actually close the gap at the level held.
			if (!requirement.boostable()
				|| !boosts.covers(requirement.skill(), have, requirement.level() - have))
			{
				gaps.allBoostable = false;
			}
		}
		if (!gaps.anyGap)
		{
			gaps.allBoostable = false;
		}
		return gaps;
	}

	private static final class SkillGaps
	{
		private boolean anyGap;
		private boolean allBoostable;
	}

	/**
	 * Every quest the account could start right now, in graph order.
	 *
	 * Ordered by id rather than by anything cleverer. Routing is out of scope
	 * for this plugin by the brief, and an ordering invented here would be a
	 * recommendation dressed as a list -- graph order is at least honestly
	 * arbitrary.
	 */
	List<QuestGraph.Quest> doable()
	{
		Deque<QuestGraph.Quest> out = new ArrayDeque<>();
		for (QuestGraph.Quest quest : graph.quests())
		{
			if (classify(quest).doable())
			{
				out.add(quest);
			}
		}
		return new java.util.ArrayList<>(out);
	}
}
